import React from 'react';
import { Card, CardContent } from './ui/card';
import { Leaf, TrendingUp, Wallet, Zap } from 'lucide-react';

const MetricCard = ({ title, value, subValue, icon: Icon, colorClass, subColorClass }) => (
    <Card className="overflow-hidden border-none shadow-md">
        <CardContent className="p-0">
            <div className="flex items-stretch">
                <div className={`w-2 ${colorClass}`} />
                <div className="flex-1 p-5">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-semibold text-slate-500 uppercase tracking-wider">{title}</span>
                        <Icon className={`h-5 w-5 ${subColorClass}`} />
                    </div>
                    <div className="flex flex-col">
                        <span className="text-2xl font-bold text-slate-900">{value}</span>
                        <span className={`text-sm font-medium ${subColorClass}`}>{subValue}</span>
                    </div>
                </div>
            </div>
        </CardContent>
    </Card>
);

const SummaryDashboard = ({ activeResults, combinedResults, activeTab }) => {
    const formatCurrency = (val) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val || 0);
    const formatNumber = (val) => new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(val || 0);

    const titlePrefix = activeTab === 'space' ? 'Space Heating' : 'Water Heating';

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <MetricCard
                title={`${titlePrefix} Reduction`}
                value={`${formatNumber(activeResults.netEmissionsReduction)} MTCO2e`}
                subValue="Saved per year"
                icon={Leaf}
                colorClass="bg-emerald-500"
                subColorClass="text-emerald-600"
            />
            <MetricCard
                title="Est. Lifetime Savings"
                value={formatCurrency(activeResults.totalSavings)}
                subValue={`Over ${activeTab === 'space' ? '15' : '12'} years`}
                icon={TrendingUp}
                colorClass="bg-blue-500"
                subColorClass="text-blue-600"
            />
            <MetricCard
                title="Upfront Difference"
                value={formatCurrency(activeResults.initialDifference)}
                subValue="HP vs Gas"
                icon={Wallet}
                colorClass="bg-amber-500"
                subColorClass="text-amber-600"
            />
            <MetricCard
                title="Payback Period"
                value={`${formatNumber(activeResults.paybackPeriod, 1)} Years`}
                subValue="Break-even point"
                icon={Zap}
                colorClass="bg-indigo-500"
                subColorClass="text-indigo-600"
            />
        </div>
    );
};

export default SummaryDashboard;
