import { useState, useMemo } from 'react';

const ELECTRICITY_EMISSIONS_FACTOR = 0.000015742; // MTCO2e/kWh
const GAS_EMISSIONS_FACTOR = 0.005; // MTCO2e/therm

export const useCalculator = (initialInputs) => {
    const [inputs, setInputs] = useState(initialInputs);

    const results = useMemo(() => {
        const calculateTech = (tech, params) => {
            const isSpace = tech === 'spaceHeating';

            // Constants from Spec Sheet
            const heatingLoad = params.heatingLoad || 60000000; // BTU/year
            const waterUsage = params.waterUsage || 1000; // kWh/person/year

            // Calculate annual energy needs
            let annualTherms, annualKWh;
            if (isSpace) {
                annualTherms = heatingLoad / (100000 * params.gasFurnaceEfficiency);
                annualKWh = (heatingLoad / 3412) / params.heatPumpCOP;
            } else {
                // Water heating logic (Pattern B can be applied here)
                annualTherms = params.annualGasUsage * (params.waterHeatingPercentage / 100);
                annualKWh = (annualTherms * 29.3) / params.heatPumpWaterHeaterEF;
            }

            // Emissions
            const annualEmissionsGas = annualTherms * GAS_EMISSIONS_FACTOR;
            const annualEmissionsHP = annualKWh * ELECTRICITY_EMISSIONS_FACTOR;
            const netEmissionsReduction = annualEmissionsGas - annualEmissionsHP;

            // Rebates (3-tier)
            const hpInitialBase = (params.unitCostHP || 0) + (params.installCostHP || 0);
            const rebateAmount = Math.min(hpInitialBase * ((params.rebatePercent || 0) / 100), params.maxRebateCap || 0) + (params.additionalCashRebate || 0);

            const initialCostGas = (params.unitCostGas || 0) + (params.installCostGas || 0);
            const initialCostHP = hpInitialBase - rebateAmount - (params.federalTaxCredit || 0);
            const initialDifference = initialCostHP - initialCostGas;


            // Lifecycle Loop
            const yearByYearData = [];
            let cumulativeCostGas = initialCostGas;
            let cumulativeCostHP = initialCostHP;
            let cumulativeCostResistance = (params.unitCostHP || 0) + (params.installCostHP || 0); // Assuming similar upfront to HP for simplicity, or just base costs. actually resistance is cheap. let's assume 0 increment for now or just tracking op cost? 
            // Spec implies comparison. Resistance heating usually low upfront, high op cost. 
            // Let's assume Resistance Upfront is roughly equal to Gas for simplicity unless specified, 
            // BUT usually we are comparing "What if I just used space heaters?". 
            // Let's stick to just tracking Accumulating Operating Cost for Resistance, starting at 0 relative difference or just OpCost?
            // "Showcase resistance electrical heat" -> likely just the high operating cost line. 
            // Let's start Resistance Cumulative at 0 for "Operating Cost Only" or align with HP?
            // Actually, let's just track the *Operating Cost* primarily, but for a fair chart, it needs an intercept.
            // Let's assume a cheap resistance install cost ($1000?) if not provided, or just match Gas?
            // Simplest: Start at Gas Cost (baseline) to show pure Op Cost divergence? 
            // OR: Just Op Costs. 
            // Decision: Let's assume Resistance System Cost is low, say $1000.
            let cumulativeCostResistive = 1000;

            const years = 20; // Default timeframe

            for (let i = 0; i <= years; i++) {
                if (i > 0) {
                    // Operating Costs (with utility inflation)
                    const gasPrice = params.gasRate * Math.pow(1 + params.utilityInflation / 100, i - 1);
                    const elecPrice = params.electricityRate * Math.pow(1 + params.utilityInflation / 100, i - 1);

                    let opCostGas = (annualTherms * gasPrice) + params.annualMaintenanceGas;
                    let opCostHP;

                    // Resistance Op Cost (COP 1.0)
                    // Energy = Load / 3412 / 1.0
                    let annualKWhResistive;
                    if (isSpace) {
                        annualKWhResistive = (heatingLoad / 3412);
                    } else {
                        annualKWhResistive = (annualTherms * 29.3); // Rough therms to kWh equivalent
                    }
                    let opCostResistive = (annualKWhResistive * elecPrice); // Minimal maintenance

                    // Pattern A: Replacement Logic for BOTH Space and Water Heating
                    // Ideally we replace the unit at end of lifespan.
                    // Space Heating
                    if (isSpace && i % params.equipmentLifespan === 0) {
                        cumulativeCostGas += params.unitCostGas || 0;
                        cumulativeCostHP += params.unitCostHP || 0;
                    }

                    // Water Heating - previously Pattern B (Degradation), now Pattern A (Replacement)
                    // User complained about "hardcoded failure".
                    if (!isSpace && i % params.equipmentLifespan === 0) { // Uses same lifespan key or compressorLife?
                        // params.compressorLife was used for degradation. Let's use equipmentLifespan for consistency if available, or compressorLife.
                        // Defaults say equipmentLifespan: 12.
                        cumulativeCostGas += params.unitCostGas || 0;
                        cumulativeCostHP += params.unitCostHP || 0;
                    }

                    // Operating Costs
                    cumulativeCostGas += opCostGas;

                    // HP Op Cost - always efficient, assuming replacement maintains efficiency
                    opCostHP = (annualKWh * elecPrice) + params.annualMaintenanceHP;
                    cumulativeCostHP += opCostHP;

                    cumulativeCostResistive += opCostResistive;

                }

                yearByYearData.push({
                    year: i,
                    gasSystem: cumulativeCostGas,
                    hpSystem: cumulativeCostHP,
                    resistiveSystem: cumulativeCostResistive,
                });
            }

            const opCostSavings = ((annualTherms * (params.gasRate || 0)) + (params.annualMaintenanceGas || 0)) - ((annualKWh * (params.electricityRate || 0)) + (params.annualMaintenanceHP || 0));
            const payback = opCostSavings !== 0 ? initialDifference / opCostSavings : 0;

            if (isNaN(payback)) {
                console.warn(`Payback is NaN for ${tech}`, { inputs: params });
            }

            return {
                annualEmissionsGas,
                annualEmissionsHP,
                netEmissionsReduction,
                initialCostGas,
                initialCostHP,
                initialDifference,
                yearByYearData,
                totalSavings: cumulativeCostGas - cumulativeCostHP,
                paybackPeriod: isNaN(payback) ? 0 : payback
            };

        };

        return {
            spaceHeating: calculateTech('spaceHeating', inputs.spaceHeating),
            waterHeating: calculateTech('waterHeating', inputs.waterHeating)
        };
    }, [inputs]);

    const handleInputChange = (category, field, value) => {
        // Ensure boolean for showResistance
        const val = field === 'showResistance' ? Boolean(value) : value;
        setInputs(prev => ({
            ...prev,
            [category]: {
                ...prev[category],
                [field]: val
            }
        }));
    };


    return { inputs, results, handleInputChange };
};
