import React from 'react';
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';

const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-white p-4 border rounded shadow-lg">
                <p className="text-sm font-bold text-slate-800 mb-2">Year {label}</p>
                {payload.map((entry, index) => (
                    <p key={index} className="text-xs" style={{ color: entry.color }}>
                        {entry.name}: {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(entry.value)}
                    </p>
                ))}
            </div>
        );
    }
    return null;
};

const CostChart = ({ data, title, showResistance }) => {
    return (
        <Card className="shadow-lg border-slate-200">
            <CardHeader>
                <CardTitle className="text-lg font-bold text-slate-800">{title}</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="h-[400px] w-full mt-4">
                    <ResponsiveContainer width="100%" height="100%">
                        <LineChart
                            data={data}
                            margin={{ top: 5, right: 30, left: 20, bottom: 25 }}
                        >
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis
                                dataKey="year"
                                label={{ value: 'Years', position: 'insideBottom', offset: -15, fontSize: 12, fill: '#64748b' }}
                                tick={{ fontSize: 11, fill: '#64748b' }}
                            />
                            <YAxis
                                label={{ value: 'Cumulative Cost ($)', angle: -90, position: 'insideLeft', fontSize: 12, fill: '#64748b' }}
                                tick={{ fontSize: 11, fill: '#64748b' }}
                                tickFormatter={(val) => `$${val / 1000}k`}
                            />
                            <Tooltip content={<CustomTooltip />} />
                            <Legend verticalAlign="top" height={36} />
                            <Line
                                type="monotone"
                                dataKey="gasSystem"
                                name="Gas System"
                                stroke="#ef4444"
                                strokeWidth={2}
                                dot={false}
                                activeDot={{ r: 4 }}
                            />
                            <Line
                                type="monotone"
                                dataKey="hpSystem"
                                name="Heat Pump System"
                                stroke="#10b981"
                                strokeWidth={2}
                                dot={false}
                                activeDot={{ r: 4 }}
                            />
                            {showResistance && (
                                <Line
                                    type="monotone"
                                    dataKey="resistiveSystem"
                                    name="Electric Resistance"
                                    stroke="#f59e0b"
                                    strokeWidth={2}
                                    strokeDasharray="5 5"
                                    dot={false}
                                />
                            )}
                        </LineChart>
                    </ResponsiveContainer>
                </div>
            </CardContent>
        </Card>
    );
};

export default CostChart;
