import React from 'react';
import { Slider } from './ui/slider';
import { Input } from './ui/input';
import { Label } from './ui/label';

const InputField = ({ label, value, onChange, min, max, step = 1, unit = "", prefix = "" }) => {
    const handleSliderChange = (vals) => {
        onChange(vals[0]);
    };

    const handleInputChange = (e) => {
        const val = e.target.value === '' ? '' : parseFloat(e.target.value);
        if (val !== '' && !isNaN(val)) {
            onChange(val);
        } else if (e.target.value === '') {
            onChange('');
        }
    };

    return (
        <div className="space-y-3 mb-6">
            <div className="flex justify-between items-center">
                <Label className="text-sm font-medium text-slate-700">{label}</Label>
                <div className="flex items-center gap-2">
                    <div className="relative">
                        {prefix && (
                            <span className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400 text-xs">
                                {prefix}
                            </span>
                        )}
                        <Input
                            type="number"
                            value={value}
                            onChange={handleInputChange}
                            className={`w-24 h-8 text-right text-sm ${prefix ? 'pl-5' : ''}`}
                        />
                    </div>
                    {unit && <span className="text-xs text-slate-500 w-8">{unit}</span>}
                </div>
            </div>
            <Slider
                value={[value || 0]}
                onValueChange={handleSliderChange}
                min={min}
                max={max}
                step={step}
                className="py-2"
            />
        </div>
    );
};

export default InputField;
