import * as React from "react"
import { cn } from "../../lib/utils"


const Slider = React.forwardRef(({ className, min = 0, max = 100, step = 1, value, onValueChange, ...props }, ref) => {
    const handleChange = (event) => {
        const newValue = parseFloat(event.target.value)
        if (onValueChange) {
            onValueChange([newValue])
        }
    }

    const val = Array.isArray(value) ? value[0] : value

    return (
        <input
            type="range"
            ref={ref}
            min={min}
            max={max}
            step={step}
            value={val}
            onChange={handleChange}
            className={cn(
                "relative flex w-full touch-none select-none items-center accent-blue-600",
                "h-1.5 rounded-full bg-gray-200 cursor-pointer appearance-none",
                "[&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-blue-600 [&::-webkit-slider-thumb]:ring-offset-white [&::-webkit-slider-thumb]:transition-colors [&::-webkit-slider-thumb]:focus-visible:outline-none [&::-webkit-slider-thumb]:focus-visible:ring-2 [&::-webkit-slider-thumb]:focus-visible:ring-blue-600 [&::-webkit-slider-thumb]:focus-visible:ring-offset-2 [&::-webkit-slider-thumb]:disabled:pointer-events-none [&::-webkit-slider-thumb]:disabled:opacity-50",
                "[&::-moz-range-thumb]:appearance-none [&::-moz-range-thumb]:h-4 [&::-moz-range-thumb]:w-4 [&::-moz-range-thumb]:border-0 [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:bg-blue-600 [&::-moz-range-thumb]:ring-offset-white [&::-moz-range-thumb]:transition-colors [&::-moz-range-thumb]:focus-visible:outline-none [&::-moz-range-thumb]:focus-visible:ring-2 [&::-moz-range-thumb]:focus-visible:ring-blue-600 [&::-moz-range-thumb]:focus-visible:ring-offset-2 [&::-moz-range-thumb]:disabled:pointer-events-none [&::-moz-range-thumb]:disabled:opacity-50",
                className
            )}
            {...props}
        />
    )
})
Slider.displayName = "Slider"

export { Slider }
