import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';

const LifecycleTable = ({ data, showResistance }) => {
    const formatCurrency = (val) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);

    // Show every 5 years for brevity + Year 0 and last year
    const displayRows = data.filter(d => d.year === 0 || d.year % 5 === 0 || d.year === data.length - 1);

    return (
        <Card className="shadow-lg border-slate-200">
            <CardHeader>
                <CardTitle className="text-lg font-bold text-slate-800">Year-by-Year Financial Comparison</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-50 text-slate-600 uppercase text-xs font-bold">
                            <tr>
                                <th className="px-4 py-3">Year</th>
                                <th className="px-4 py-3">Gas Cost</th>
                                <th className="px-4 py-3">Heat Pump Cost</th>
                                {showResistance && <th className="px-4 py-3">Resistance Cost</th>}
                                <th className="px-4 py-3">HP Savings (vs Gas)</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {displayRows.map((row) => (
                                <tr key={row.year} className="hover:bg-slate-50 transition-colors">
                                    <td className="px-4 py-3 font-medium text-slate-900">{row.year === 0 ? 'Initial' : `Year ${row.year}`}</td>
                                    <td className="px-4 py-3 text-slate-600">{formatCurrency(row.gasSystem)}</td>
                                    <td className="px-4 py-3 text-slate-600">{formatCurrency(row.hpSystem)}</td>
                                    {showResistance && <td className="px-4 py-3 text-amber-600">{formatCurrency(row.resistiveSystem)}</td>}
                                    <td className="px-4 py-3 font-bold text-blue-600">
                                        {formatCurrency(row.gasSystem - row.hpSystem)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </CardContent>
        </Card>
    );
};

export default LifecycleTable;
